-- One-off fix: add the 108 April 2025 payments that the April audit found in
-- Kibet's "Payment Analysis ..." Q2 2025 sheet but not in the system
-- ("2025 4 April System vs Source - Updated.xlsx", sheet "Missing from System").
-- 106 were cash payments (source phone = "Cash payment"): phone numbers were
-- found in the system's other transactions for 89 of them (sheet "Phone Matches");
-- 17 are added WITHOUT a phone and flagged. Every row's notes say which.
--   cash - phone confirmed                      76 rows  KES   7,723,200
--   cash - phone confirmed - duplicate check    13 rows  KES   1,280,000
--   cash - phone missing                        17 rows  KES   1,735,600
--   source phone - duplicate check               2 rows  KES     151,200
--   TOTAL                                      108 rows  KES  10,890,000
-- Rows needing review carry a flag_reason (duplicate check or missing phone),
-- so they show as flagged in the app. Payment dates are the TRUE dates from the
-- source, so these rows must be EXCLUDED from the later +1 day importer-bug
-- backfill - they are listed in perdiem_requests_backup_2025_04_cash_inserts.
-- Expected after running: April 2025 = 278 rows / KES 23,071,800 (the audit's
-- corrected April total).
-- NOT a numbered migration - run manually in the Supabase SQL Editor.
-- The whole thing runs in one transaction; any failed check rolls it all back.

begin;

create temp table new_events (id text primary key, venue_name text, venue_id text, pay_date text) on commit drop;

create temp table new_rows (id text primary key, participant_name text, participant_phone text, event_id text,
  pay_date text, notes text, flag_reason text, transport double precision, dsa double precision, total double precision, kind text) on commit drop;

-- Step 1: Safety checks.
do $$
declare n_apr int; s_apr double precision;
begin
  select count(*), coalesce(sum(total_perdiem), 0) into n_apr, s_apr
  from perdiem_requests where date between '2025-04-01' and '2025-04-30';
  if n_apr <> 170 or s_apr <> 12181800 then
    raise exception 'April is not in the expected state: % rows / KES % (expected 170 / 12181800) - has something already been added?', n_apr, s_apr;
  end if;
  if (select count(*) from new_rows) <> 108 or (select sum(total) from new_rows) <> 10890000 then
    raise exception 'Row list is not 108 rows / KES 10890000';
  end if;
  if exists (select 1 from perdiem_requests p join new_rows r on p.id = r.id) or exists (select 1 from events e join new_events n on e.id = n.id) then
    raise exception 'An id already exists';
  end if;
  if (select count(*) from venues where id in (select venue_id from new_events)) <> 3
     or not exists (select 1 from events where id = 'df4c9611-3800-4b5d-923b-3f7f95e0c131') then
    raise exception 'Expected venues / County L4 & 5 event not found';
  end if;
  -- None of the new rows may already be in the system for the same person, event day and amount.
  if exists (
    select 1 from new_rows r join perdiem_requests p
      on p.date = r.pay_date and p.total_perdiem = r.total
     and r.participant_phone is not null and right(p.participant_phone, 9) = right(r.participant_phone, 9)) then
    raise exception 'One of these payments is already in the system on the same date';
  end if;
end $$;

-- Step 2: The three cash-payment events (Workshop/Conference at each venue).
select id, '87283dbf-d590-4f66-b28d-ffe8023a1f54', 'Workshop/Conference', now(), array[pay_date], 'Workshop', venue_id, venue_name, '', 'Imported (historical)'
from new_events;

-- Step 3: The payments.
  id, client_id, participant_id, participant_name, participant_phone, event_id, event_name, location, date, status,
  notes, other_staff, transport_allowance, dsa_allowance, total_perdiem, imported_at, flag_reason, is_overpayment, recovered_amount)
select id, '87283dbf-d590-4f66-b28d-ffe8023a1f54', null, participant_name, participant_phone, event_id, 'Workshop/Conference', '', pay_date, 'Paid',
  notes, true, transport, dsa, total, now(), flag_reason, false, 0
from new_rows;

-- Step 4: Backup / undo list. Undo with:
--   delete from perdiem_requests where id in (select id from perdiem_requests_backup_2025_04_cash_inserts where kind <> 'event');
--   delete from events where id in (select id from perdiem_requests_backup_2025_04_cash_inserts where kind = 'event');
create table perdiem_requests_backup_2025_04_cash_inserts as
  select id, kind, pay_date, total, now() as inserted_at from new_rows
  union all
  select id, 'event', pay_date, null, now() from new_events;

-- Step 5: Check the result before committing.
do $$
declare n_apr int; s_apr double precision;
begin
  select count(*), coalesce(sum(total_perdiem), 0) into n_apr, s_apr
  from perdiem_requests where date between '2025-04-01' and '2025-04-30';
  if n_apr <> 278 or s_apr <> 23071800 then
    raise exception 'April after insert is % rows / KES % (expected 278 / 23071800)', n_apr, s_apr;
  end if;
end $$;

commit;

-- Step 6: Verify - expect April 2025 = 278 rows / KES 23,071,800, and the split below.
select kind, count(*), sum(total) from perdiem_requests_backup_2025_04_cash_inserts where kind <> 'event' group by kind order by kind;
select count(*) as april_rows, sum(total_perdiem) as april_total from perdiem_requests where date between '2025-04-01' and '2025-04-30';
